<?php require __DIR__.'/bootstrap.php'; require_auth(); $pdo=get_db(); $total=$pdo->query('SELECT COUNT(*) FROM suppliers')->fetchColumn(); $open=$pdo->query("SELECT COUNT(*) FROM bids WHERE status IN ('submitted','review','draft')")->fetchColumn(); $fill=$pdo->query('SELECT AVG(fillRate) FROM suppliers')->fetchColumn(); $spend=$pdo->query('SELECT SUM(spendYtd) FROM suppliers')->fetchColumn(); json(['kpis'=>['totalSuppliers'=>(int)$total,'openBids'=>(int)$open,'fillRate'=>round((float)$fill,1),'spendYtd'=>(int)$spend]]);
